/**
 * Error reporting. Off unless the build carries a Sentry DSN, so development
 * and tests never phone home. What is sent describes the app, not the person:
 * no identities, no addresses, no request bodies, no query strings, and
 * messages with an e-mail address in them are redacted before they leave
 * the device.
 */
import * as Sentry from '@sentry/react';
import { platform } from './platform/index.js';

const EMAIL = /[\w.+-]+@[\w-]+\.[\w.-]+/g;

/** Failures that are the network's, not ours: the app already handles being offline. */
const IGNORED = [
  /Failed to fetch/,
  /Load failed/,
  /NetworkError/,
  /network request failed/i,
  /AbortError/,
  // Chrome's "the page is unloading" cancellation of speech and fetches.
  /The operation was aborted/,
];

/**
 * An address without its query string or fragment. Queries carry things
 * that must not leave the device: the consent screen's `request=` id, a
 * sign-in's return path, a search.
 */
export function withoutQuery(url: string): string {
  const cut = url.search(/[?#]/u);
  return cut === -1 ? url : url.slice(0, cut);
}

/**
 * The release events are filed under: `lexpad-web@<version>`, so the web
 * app's releases never collide with the API's (`lexpad-api@…`) in the same
 * organisation. Sentry discards a release with a slash, a backslash or a
 * line break, or longer than 200 characters, so those are repaired. The
 * source-map upload in vite.config.ts names its release the same way.
 */
export function releaseName(version: string): string {
  return `lexpad-web@${version.trim()}`.replace(/[/\\\n\r\t]/gu, '-').slice(0, 200);
}

/** The breadcrumb fields that hold an address (fetch, xhr, navigation). */
const URL_FIELDS = ['url', 'from', 'to'] as const;

export function startMonitoring(): void {
  const dsn = import.meta.env.VITE_SENTRY_DSN;
  if (dsn === undefined || dsn === '') return;
  Sentry.init({
    dsn,
    release: releaseName(platform.env.appVersion),
    environment: import.meta.env.MODE,
    sendDefaultPii: false,
    // Errors only. Performance and replay would multiply the volume, and the
    // free plan is for the crashes we cannot see otherwise.
    tracesSampleRate: 0,
    ignoreErrors: IGNORED,
    initialScope: { tags: { platform: platform.env.platform, embedded: String(platform.env.embedded) } },
    beforeSend(event) {
      if (event.message !== undefined) event.message = event.message.replace(EMAIL, '[e-mail]');
      for (const exception of event.exception?.values ?? []) {
        if (exception.value !== undefined) exception.value = exception.value.replace(EMAIL, '[e-mail]');
      }
      delete event.user;
      if (event.request) {
        delete event.request.cookies;
        delete event.request.headers;
        delete event.request.query_string;
        if (event.request.url !== undefined) event.request.url = withoutQuery(event.request.url);
      }
      for (const crumb of event.breadcrumbs ?? []) scrubBreadcrumb(crumb);
      return event;
    },
    beforeBreadcrumb(crumb) {
      scrubBreadcrumb(crumb);
      return crumb;
    },
  });
}

function scrubBreadcrumb(crumb: Sentry.Breadcrumb): void {
  const data = crumb.data;
  if (data !== undefined) {
    for (const field of URL_FIELDS) {
      const value = data[field] as unknown;
      if (typeof value === 'string') data[field] = withoutQuery(value);
    }
  }
  if (crumb.message !== undefined && crumb.category === 'navigation') {
    crumb.message = withoutQuery(crumb.message);
  }
}

/** Reports a caught failure that the app survived but someone should see. */
export function reportError(error: unknown, context?: Record<string, string>): void {
  Sentry.captureException(error, context === undefined ? undefined : { tags: context });
}

export { ErrorBoundary } from '@sentry/react';
