/**
 * Waiting before trying again, without every client trying again together.
 *
 * "Full jitter": each wait is a random point in a window that doubles with
 * each failure, up to a cap. Thousands of clients that failed in the same
 * second (a deploy, an overload) then come back spread over the window
 * instead of all at once, which is what knocks a recovering server over.
 * A floor the server asked for (`Retry-After`) is added, never replaced: a
 * random wait shorter than the floor would put everyone back at the floor.
 */

/** The window for the given attempt (0 = the first retry): `base · 2^attempt`, capped. */
export function backoffWindow(attempt: number, baseMs: number, capMs: number): number {
  return Math.min(capMs, baseMs * 2 ** Math.max(0, attempt));
}

/**
 * How long to wait before the next attempt: the server's floor plus a random
 * point in the window. `random` is a seam for tests.
 */
export function backoffDelay(
  attempt: number,
  options: { baseMs: number; capMs: number; floorMs?: number; random?: () => number },
): number {
  const random = options.random ?? Math.random;
  const jitter = Math.floor(random() * backoffWindow(attempt, options.baseMs, options.capMs));
  return Math.min(options.capMs, (options.floorMs ?? 0) + jitter);
}

/**
 * Reads a `Retry-After` value: delay-seconds or an HTTP date. Undefined when
 * there is none or it cannot be read.
 */
export function parseRetryAfter(
  value: string | null | undefined,
  now: number = Date.now(),
): number | undefined {
  if (value === null || value === undefined) return undefined;
  const trimmed = value.trim();
  if (trimmed === '') return undefined;
  if (/^\d+$/.test(trimmed)) return Number(trimmed) * 1000;
  // An HTTP date names its day and month; a bare "-3" is not a date.
  if (!/[a-z]/i.test(trimmed)) return undefined;
  const at = Date.parse(trimmed);
  if (Number.isNaN(at)) return undefined;
  return Math.max(0, at - now);
}

/**
 * Resolves after `ms`, or rejects with the signal's reason when it is
 * aborted first.
 */
export function sleep(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted === true) {
      reject(signal.reason as Error);
      return;
    }
    const onAbort = (): void => {
      clearTimeout(timer);
      reject(signal?.reason as Error);
    };
    const timer = setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}
